<?php
// Progress is stored with the upload in the existing InnoDB transaction journal.
// A chunk's stock effects and cursor commit together; a lost HTTP response cannot replay them.
function wb_raw($id){$b=om_query('SELECT * FROM om_uploads WHERE id=?',[(int)$id])->fetch();if(!$b)throw new Exception('Upload not found.');$b['meta']=json_decode($b['meta_json'],true)?:[];return $b;}
function wb_job($b){return json_decode($b['result_json']??'{}',true)['batch']??null;}
function wb_access($b){om_require();if(!in_array(access_profile(),['Admin','Operations Lead'],true)||($b['created_by']!=current_user()['id']&&access_profile()!=='Admin'))throw new Exception('Only the uploader or Admin may process this status upload.');if($b['kind']!=='Status'||!empty($b['meta']['manual']))throw new Exception('Use a file-based Update Status upload.');}
function wb_fingerprint($b){return hash('sha256',$b['rows_json'].'|'.$b['meta_json'].'|'.$b['revision']);}
function wb_state($b){$j=wb_job($b);if(!$j)throw new Exception('Batch processing has not started.');return ['id'=>(int)$b['id'],'token'=>$j['token'],'state'=>$j['state'],'processed'=>(int)$j['cursor'],'total'=>(int)$j['total'],'counts'=>$j['counts'],'message'=>$j['message']??'','updated_at'=>$j['updated_at'],'complete'=>$b['status']==='Confirmed'];}
function wb_save($id,$data,$complete=false){$json=json_encode($data,JSON_THROW_ON_ERROR);om_query('UPDATE om_uploads SET result_json=?,status=?,confirmed_at=IF(?=1,NOW(),confirmed_at) WHERE id=?',[$json,$complete?'Confirmed':'Processing',$complete?1:0,$id]);}
function wb_start($id,$digest,$ack){return process_transaction(function()use($id,$digest,$ack){om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[$id])->fetch();$raw=wb_raw($id);wb_access($raw);if(!$ack)throw new Exception('Review and acknowledge the validation results.');if(wb_job($raw))return wb_state($raw);$b=om_upload($id);om_owner($b);$p=om_plan($b);if(!hash_equals($p['digest'],(string)$digest))throw new Exception('Stock, registration or review changed. Reopen validation before confirming.');if(!$p['orders'])throw new Exception('No orders to process.');$now=date('Y-m-d H:i:s');$j=['version'=>1,'token'=>bin2hex(random_bytes(24)),'state'=>'Running','cursor'=>0,'total'=>count($p['orders']),'counts'=>[],'revision'=>(int)$b['revision'],'fingerprint'=>wb_fingerprint($raw),'started_by'=>(int)current_user()['id'],'started_at'=>$now,'updated_at'=>$now,'message'=>''];wb_save($id,['batch'=>$j,'counts'=>[],'validation'=>$p['orders']]);om_event(null,$id,'Status batch started',['total'=>$j['total'],'user_id'=>current_user()['id'],'stock_changed'=>false]);return wb_state(wb_raw($id));});}
function wb_alert($id){$o=om_order($id);$cfg=om_alert_settings();$today=date('Y-m-d');$a=oa_aging($o,$today);$high=$a['aging']||($a['threshold']===null&&$a['days']>=(int)$cfg['high_days']);$open=$o['monitoring']!=='Resolved'||$o['aftersales_resolution']==='Return Expected'||$o['exception_text']!=='';$alert=$open&&($o['exception_text']||$high||($o['followup_date']&&$o['followup_date']<=$today));om_query("UPDATE om_alerts SET resolved=1 WHERE alert_key IN (?,?)",['order-'.$id,'shortage-'.$id]);if($alert)om_query('INSERT INTO om_alerts(alert_key,order_id,owner_id,title,resolved) VALUES(?,?,?,?,0) ON DUPLICATE KEY UPDATE owner_id=VALUES(owner_id),title=VALUES(title),resolved=0',['order-'.$id,$id,$o['owner_id'],($high?'HIGH · ':'').$o['order_no'].' · '.(oc_exception($o)?:($o['aftersales_resolution']==='Return Expected'?'Return expected':$o['platform_status'].' pending '.$a['days'].' days'))]);foreach(om_query('SELECT product_id FROM om_reservations WHERE order_id=? AND qty>0',[$id]) as $l)if(om_available($l['product_id'])<0||om_available($l['product_id'],$o['platform'])<0){om_query('INSERT INTO om_alerts(alert_key,order_id,owner_id,title,resolved) VALUES(?,?,?,?,0) ON DUPLICATE KEY UPDATE owner_id=VALUES(owner_id),title=VALUES(title),resolved=0',['shortage-'.$id,$id,$o['owner_id'],'HIGH · Reservation shortage / allocation review · '.$o['order_no']]);break;}}
function wb_fresh($b,$initial){$o=$initial['order_record'];if($o){$fresh=om_order($o['id'],true);if((int)$fresh['revision']!==(int)$o['revision'])return null;}
 if($initial['action']==='Missing from covering export'){$r=$initial;$r['order_record']=$fresh;$m=ot_order_meta($b,'');if(($fresh['last_snapshot']&&$fresh['last_snapshot']>=$m['snapshot'])||($fresh['monitoring']==='Resolved'&&$fresh['aftersales_resolution']!=='Return Expected'))return null;return $r;}
 // Initially blocked rows were not approved for stock movement. Keep them for a separate review.
 if($initial['errors'])return $initial;
 $sub=$b;$sub['_batch_scope']=true;$sub['rows']=$initial['lines'];return om_plan($sub)['orders'][0];}
function wb_tick($id,$token,$cursor,$mode='work'){$lock=inventory_write_lock();try{return process_transaction(function()use($id,$token,$cursor,$mode){om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[$id])->fetch();$b=wb_raw($id);wb_access($b);$data=json_decode($b['result_json']??'{}',true,512,JSON_THROW_ON_ERROR);$j=$data['batch']??null;if(!$j||!hash_equals($j['token'],(string)$token))throw new Exception('Reopen this upload to continue the saved batch.');if(!in_array($mode,['work','state','pause','resume'],true))throw new Exception('Unknown batch action.');if($b['status']==='Confirmed'||$mode==='state')return wb_state($b);if($b['status']!=='Processing')throw new Exception('This upload is not processing.');if(!hash_equals($j['fingerprint'],wb_fingerprint($b)))throw new Exception('Upload data changed. Processing stopped; contact Admin to review the saved progress.');
 if($mode==='pause'||$mode==='resume'){$j['state']=$mode==='pause'?'Paused':'Running';$j['message']='';$j['updated_at']=date('Y-m-d H:i:s');$data['batch']=$j;wb_save($id,$data);om_event(null,$id,$mode==='pause'?'Status batch paused':'Status batch resumed',['processed'=>$j['cursor'],'total'=>$j['total'],'user_id'=>current_user()['id'],'stock_changed'=>false]);return wb_state(wb_raw($id));}
 if($j['state']!=='Running'||(int)$cursor!==(int)$j['cursor'])return wb_state($b);
 // Short requests let other inventory operations proceed between chunks.
 $began=microtime(true);$from=$j['cursor'];$processed=0;unset($GLOBALS['OM_RESERVED'],$GLOBALS['OA_REPORTS'],$GLOBALS['OR_INDEX']);
 while($j['cursor']<$j['total']&&$processed<20&&($processed===0||microtime(true)-$began<3)){$i=$j['cursor'];$old=$data['validation'][$i];$r=wb_fresh($b,$old);if($r===null){$r=$old;$r['action']='Needs Checking';$r['errors']=['Order changed after confirmation started. Its newer status and stock were retained; review this order separately.'];if($old['order_record'])om_event($old['order_record']['id'],$id,'Batch retained newer order',['order'=>$old['order'],'stock_changed'=>false]);}else{om_apply_order($b,$r);if($r['order_record'])wb_alert($r['order_record']['id']);}$j['counts'][$r['action']]=($j['counts'][$r['action']]??0)+1;$data['validation'][$i]=$r;$j['cursor']++;$processed++;}
 $complete=$j['cursor']===$j['total'];$j['state']=$complete?'Complete':'Running';$j['updated_at']=date('Y-m-d H:i:s');$j['message']='';$data['batch']=$j;$data['counts']=$j['counts'];wb_save($id,$data,$complete);om_event(null,$id,'Status batch checkpoint',['from'=>$from,'processed'=>$j['cursor'],'total'=>$j['total'],'user_id'=>current_user()['id'],'complete'=>$complete]);if($complete)audit('Confirm Status orders','Order Monitoring',(string)$id,json_encode(['counts'=>$j['counts'],'batch_processing'=>true,'started_by'=>$j['started_by'],'completed_by'=>current_user()['id']]));return wb_state(wb_raw($id));});}finally{inventory_write_unlock($lock);}}
function wb_page($b){wb_access($b);$j=wb_job($b);$state=wb_state($b);$id=(int)$b['id'];os_tabs('Status',$b['platform']);echo '<link rel="stylesheet" href="assets/order_status_batches.css"><section class="card wb-panel" id="wbPanel" data-upload="'.$id.'" data-token="'.e($j['token']).'" data-csrf="'.e(csrf_token()).'"><div class="om-hero"><div><h2>Status Upload Progress</h2><p>'.e($b['platform']).' · Upload #'.$id.' · '.e($b['filename']).'</p></div><span class="badge info" id="wbState">'.e($j['state']).'</span></div><p>Updates run in small batches. You can return to this upload and continue from its saved progress.</p><progress id="wbProgress" value="'.$j['cursor'].'" max="'.$j['total'].'"></progress><div class="wb-progress-text" id="wbCount">'.$j['cursor'].' of '.$j['total'].' orders checked</div><p class="muted">Each completed batch is saved with its stock movements and history. First dispatch deducts once; Delivered / Completed does not deduct again. Actual returns are received in Inflow.</p><div id="wbMessage" role="status" aria-live="polite"></div><div class="wb-counts" id="wbCounts"></div><div class="wb-actions"><button class="btn primary" type="button" id="wbResume">Resume Processing</button><button class="btn secondary" type="button" id="wbPause">Pause After Current Batch</button><a class="btn ghost" href="?page=outflow&amp;entry=history&amp;platform='.e(rawurlencode($b['platform'])).'">Upload History</a><a class="btn primary" id="wbDone" hidden href="?page=outflow&amp;entry=status&amp;platform='.e(rawurlencode($b['platform'])).'&amp;upload_id='.$id.'">View Results</a></div><p class="small muted">Closing this page pauses further requests after the current batch. Do not re-upload the file to resume.</p></section><script src="assets/order_status_batches.js" defer></script>';}
